 37	// ---------------------------------------------------------------------------
 38	// Types
 39	// ---------------------------------------------------------------------------
 40	type FooterProps = {
 41	  /** Contentful FooterConfigEntry. Pass FOOTER_FIXTURE from contentfulFixture.ts in stories/tests. */
 42	  data: FooterConfigEntry;
 43	  copyrightYear?: number;
 44	  /** Forces SubscribeSection into its post-submit state. For Storybook/tests only. */
 45	  initialSubscribed?: boolean;
 46	  /**
 47	   * Opt in to the HPC-035 first/last-name capture modal. Defaults to false: SFCC-55 ships the
 48	   * Stay in Touch section as an input plus submit button only, and the modal has no design yet.
 49	   */
 50	  enableNameCapture?: boolean;
 51	  /** Click handler for the wordmark. Mirrors the header's onLogoClick prop, defaulting to
 52	   *  noop so the presentational Footer never navigates on its own. */
 53	  onLogoClick?: () => void;
 54	  /** href for the Privacy Policy link inside the subscribe modal (HPC-037). Locale-aware at runtime. */
 55	  privacyPolicyHref?: string;
 56	};
 57	
 58	// ---------------------------------------------------------------------------
 59	// All footer styling lives in theme/components/footer.ts and is consumed via
 60	// useMultiStyleConfig('ZimmFooter') → __css. Nothing is styled at the call site.
 61	// ---------------------------------------------------------------------------
 62	
 63	// Subscribe heading ("Keep in Touch") — same type scale as navigation, distinct colour and lineHeight
 64	// colour.ts note: text.inverseGrey and text.muted are both #969696 as of develop commit 6fa8e92
 65	// lineHeight override: textStyles.navigation says 'normal' (≈14.4px at 12px font), but Figma
 66	// wants 14px, so subscribeHeading sets lineHeight explicitly to --zimm-font-lineheight-2xs.
 67	// These values now live in theme/components/footer.ts's subscribeHeading part, not here.
 68	// ---------------------------------------------------------------------------
 69	// Subscribe modal (HPC-035 + HPC-037)
 70	// Rendered via createPortal so the overlay escapes the footer stacking context.
 71	// ---------------------------------------------------------------------------
 72	// HPC-037 copy — update when UX supplies final content
 73	const PRIVACY_CONSENT_COPY = 'By providing your details, you agree to receive email updates from Zimmermann. View our';
 74	const ACCESSIBILITY_DISCLAIMER_COPY =
 75	  'Zimmermann is committed to providing accessible services. ' +
 76	  'If you experience any difficulty, please contact us for assistance.';
 77	
 78	type SubscribeModalProps = {
 79	  isOpen: boolean;
 80	  onClose: () => void;
 81	  onSubmit: (firstName: string, lastName: string) => void;
 82	  privacyPolicyHref: string;
 83	};
 84	
 85	const SubscribeModal = ({ isOpen, onClose, onSubmit, privacyPolicyHref }: SubscribeModalProps) => {
 86	  const { mounted, formRef, firstFocusRef } = useSubscribeModal({ isOpen, onClose });
 87	  const styles = useMultiStyleConfig(ZIMM_FOOTER_RECIPE, {});
 88	
 89	  const handleFormSubmit = (e: React.FormEvent<HTMLFormElement>) => {
 90	    e.preventDefault();
 91	    const form = e.currentTarget;
 92	    // namedItem returns Element | RadioNodeList | null. The cast keeps `| null` rather than
 93	    // asserting it away — these fields are always single <input>s rendered by ZimmTextInput,
 94	    // but a missing field must stay a null the `?.` below can actually catch. Same pattern as
 95	    // zimmInputAction's handleSubmit.
 96	    const firstName = (form.elements.namedItem('firstName') as HTMLInputElement | null)?.value ?? '';
 97	    const lastName = (form.elements.namedItem('lastName') as HTMLInputElement | null)?.value ?? '';
 98	    onSubmit(firstName.trim(), lastName.trim());
 99	  };
100	
101	  const handleBackdropClick = (e: React.MouseEvent<HTMLDivElement>) => {
102	    if (e.target === e.currentTarget) onClose();
103	  };
104	
105	  if (!mounted || !isOpen) return null;
106	
107	  return createPortal(
108	    <chakra.div role="presentation" onClick={handleBackdropClick} __css={styles.modalOverlay}>
109	      <chakra.div
110	        role="dialog"
111	        aria-modal="true"
112	        aria-labelledby="zimm-subscribe-modal-title"
113	        aria-describedby="zimm-subscribe-modal-consent"
114	        __css={styles.subscribeModalPanel}
115	      >
116	        <form ref={formRef} onSubmit={handleFormSubmit} noValidate>
117	          {/* Title */}
118	          <chakra.h2 id="zimm-subscribe-modal-title" __css={styles.modalTitle}>
119	            Join Us
120	          </chakra.h2>
121	
122	          {/* First Name */}
123	          <chakra.div ref={firstFocusRef} __css={styles.modalField}>
124	            <ZimmTextInput label="First Name" name="firstName" />
125	          </chakra.div>
126	
127	          {/* Last Name */}
128	          <chakra.div __css={styles.modalFieldLast}>
129	            <ZimmTextInput label="Last Name" name="lastName" />
130	          </chakra.div>
131	
132	          {/* Privacy consent copy (HPC-037) */}
133	          <chakra.p id="zimm-subscribe-modal-consent" __css={styles.modalConsent}>
134	            {PRIVACY_CONSENT_COPY}{' '}
135	            {/* Same guard as the contact channels: privacyPolicyHref is a prop, so a caller
136	                can supply anything. Unsafe or absent renders the label as plain text rather
137	                than an anchor that goes nowhere. */}
138	            {isSafeHref(privacyPolicyHref) ? (
139	              <chakra.a href={privacyPolicyHref} __css={styles.modalConsentLink}>
140	                Privacy Policy
141	              </chakra.a>
142	            ) : (
143	              <chakra.span __css={styles.modalConsentLink}>Privacy Policy</chakra.span>
144	            )}
145	            .
146	          </chakra.p>
147	
148	          {/* Accessibility disclaimer (HPC-037) */}
149	          <chakra.p __css={styles.modalDisclaimer}>{ACCESSIBILITY_DISCLAIMER_COPY}</chakra.p>
150	
151	          {/* Actions */}
152	          <chakra.div __css={styles.modalActions}>
153	            <ZimmButton variant="secondary" size="medium" label="Cancel" type="button" onClick={onClose} />
154	            <ZimmButton variant="primary" size="medium" label="Continue" type="submit" />
155	          </chakra.div>
156	        </form>
157	      </chakra.div>
158	    </chakra.div>,
159	    document.body,
160	  );
