403	// ---------------------------------------------------------------------------
404	// Footer
405	// ---------------------------------------------------------------------------
406	
407	/**
408	 * Zimmermann global footer — presentational. Receives its content as props and
409	 * fetches nothing, matching every other Contentful-backed component in the repo
410	 * (`DuplexSection`, `HeroBanner`, `ProductHero`, `VideoEmbed`).
411	 *
412	 * `data` is required by design: static content belongs in the story or in the
413	 * container below, never baked into the component that renders production UI.
414	 * Omneo email submit and Cookie Settings are separate stories (HPC-035, HPC-038).
415	 */
416	export const Footer = ({
417	  data,
418	  copyrightYear = new Date().getFullYear(),
419	  initialSubscribed = false,
420	  privacyPolicyHref = '#',
421	  onLogoClick = noop,
422	  enableNameCapture = false,
423	}: FooterProps) => {
424	  const {
425	    subscribeHeading,
426	    subscribeBody,
427	    navGroups,
428	    legalLinks = [],
429	    copyrightOwner,
430	    phoneHref,
431	    whatsAppHref,
432	    emailHref,
433	  } = data.fields;
434	
435	  const legalItems = legalLinks.map((e) => ({ label: e.fields.label, href: e.fields.href }));
436	  const styles = useMultiStyleConfig(ZIMM_FOOTER_RECIPE, {});
437	
438	  return (
439	    <chakra.footer role="contentinfo" __css={styles.container}>
440	      <chakra.div __css={styles.main}>
441	        <chakra.div __css={styles.contentRow}>
442	          <chakra.div __css={styles.subscribe}>
443	            <SubscribeSection
444	              heading={subscribeHeading ?? ''}
445	              body={subscribeBody ?? ''}
446	              initialSubscribed={initialSubscribed}
447	              privacyPolicyHref={privacyPolicyHref}
448	              enableNameCapture={enableNameCapture}
449	            />
450	          </chakra.div>
451	
452	          <chakra.div __css={styles.links}>
453	            <chakra.div __css={styles.linksInner}>
454	              {navGroups.map((group) => (
455	                <chakra.div key={group.sys.id} __css={styles.linkCol}>
456	                  {/* Figma section column: flex-col gap-16px — the column gap replaces
457	                      marginBottom on the heading. Contact heading has a 4px left offset, which
458	                      is why it selects a different part rather than patching this one. */}
459	                  <chakra.p
460	                    __css={group.fields.showContactChannels ? styles.columnHeadingContact : styles.columnHeading}
461	                  >
462	                    {group.fields.heading}
463	                  </chakra.p>
464	                  {/* Figma Links div (2228:19423): flex-col, items-start, width 100%, gap 0.
465	                      DELIBERATE DEVIATION: Figma puts the Contact items at x=0 while indenting
466	                      only its heading 4px (wrapper 40000407:22289) — About and Help headings sit
467	                      flush at 0, so that asymmetry reads as a stray wrapper rather than intent.
468	                      We indent the Contact items to match their heading so the column aligns as a
469	                      unit. The icon row below needs no indent: its 24px box centres a 16px glyph,
470	                      so the glyph edge already lands at 4px. Pending Kiera. */}
471	                  <chakra.ul __css={styles.linkList}>
472	                    {group.fields.links.map((link) => (
473	                      <chakra.li
474	                        key={link.sys.id}
475	                        // Part selection, not composition: the three <li> treatments (plain,
476	                        // Contact-indented, hug-width) are defined in footer.ts. Hug wins over
477	                        // the indent because it is the rule that changes the layout — a label
478	                        // that needs both would need its own part, and none exists today.
479	                        // See footer.ts's linkListItemHug / linkListItemContact for the why.
480	                        __css={
481	                          link.fields.label.includes(NBSP)
482	                            ? styles.linkListItemHug
483	                            : group.fields.showContactChannels
484	                            ? styles.linkListItemContact
485	                            : styles.linkListItem
486	                        }
487	                      >
488	                        {/* Each item h-[24px] items-center, no gap. ZimmNavItem's baseStyle supplies
489	                            minHeight 24px, whiteSpace normal (so the label below can wrap) and uppercase. */}
490	                        <ZimmNavItem href={link.fields.href} label={link.fields.label} inverse />
491	                      </chakra.li>
492	                    ))}
493	                    {/* Contact channels are the LAST CHILD OF THE LIST, not a sibling of it —
494	                        Figma's Icon-list (40002081:14616) sits inside Links at y=72, directly
495	                        after "CONNECT WITH US" ends at y=72, so only its own 4px padding-top
496	                        separates them. Rendered outside the <ul> it instead picked up linkCol's
