// Subscribe section
// ---------------------------------------------------------------------------
// 'unavailable' shown until HPC-036 (Omneo) lands; prevents false "You're on the list!" feedback.
// 'success'/'error' set only after a confirmed/failed Omneo response (post HPC-036).
type SubmitState = 'idle' | 'unavailable' | 'success' | 'error';

// The HPC-036 sign-up payload: footer email (HPC-034) + modal names (HPC-035).
// Assembled across two steps, POSTed to Omneo → Emarsys when the integration lands.
type PendingSignup = { email: string; firstName: string; lastName: string };

type SubscribeSectionProps = {
  heading: string;
  body: string;
  initialSubscribed?: boolean;
  privacyPolicyHref: string;
  enableNameCapture?: boolean;
};

const SUBSCRIBE_SUCCESS_MESSAGE = "You're on the list! Be the first to know about new collections and new arrivals.";
const SUBSCRIBE_UNAVAILABLE_MESSAGE = 'Subscription is temporarily unavailable. Please try again later.';

const SubscribeSection = ({
  heading,
