  const styles = useMultiStyleConfig(ZIMM_FOOTER_RECIPE, {});

  const handleEmailSubmit = (email: string) => {
    pendingSignupRef.current.email = email;
    if (enableNameCapture) {
      setModalOpen(true);
      return;
    }
    // Descoped path, and the default. SFCC-55's AC scopes this section to "an email input field
    // and submit button as a placeholder component" and defers the Omneo sign-up to a separate
    // story. The name-capture modal is HPC-035/HPC-037 (both confirmed in .docs/prd/homepage.md
    // §6) but has no Figma node — all nine of its theme parts are undesigned, unlike the 27
    // Figma-referenced parts around it. So it does not ship enabled: submitting a valid email
    // goes straight to the placeholder message. Flip this prop on once Kiera supplies the design
    // and HPC-035 is scheduled; the modal and its coverage are already built and tested.
    setSubmitState('unavailable');
    pendingSignupRef.current = { email: '', firstName: '', lastName: '' };
  };

  const handleModalSubmit = (firstName: string, lastName: string) => {
    pendingSignupRef.current = { ...pendingSignupRef.current, firstName, lastName };
    // PLACEHOLDER until HPC-036 (Omneo integration) lands: POST pendingSignupRef.current here.
    // On confirmed response → setSubmitState('success'). On failure → setSubmitState('error').
    // 'unavailable' is shown until the integration is live; never show false success.
    setModalOpen(false);
    setSubmitState('unavailable');
    // Nothing was sent, so nothing needs retaining — the record holds customer PII and there
    // is no request for it to outlive. When HPC-036 adds the POST above, this reset stays; it
    // just moves to after a confirmed response. React memory only, never storage, never logged.
    pendingSignupRef.current = { email: '', firstName: '', lastName: '' };
  };

  return (
    <div>
      <chakra.p __css={styles.subscribeHeading}>{heading}</chakra.p>
      <chakra.p __css={styles.subscribeBody}>{body}</chakra.p>
      <chakra.div aria-live="polite" __css={styles.subscribeControl}>
        {submitState === 'idle' && (
          <ZimmInputAction
            label="Email"
            type="email"
            name="footer-email"
            icon="chevron-right"
            buttonLabel="Subscribe"
            inverse
            onSubmit={handleEmailSubmit}
          />
        )}
        {submitState === 'success' && <chakra.p __css={styles.subscribeSuccess}>{SUBSCRIBE_SUCCESS_MESSAGE}</chakra.p>}
        {(submitState === 'unavailable' || submitState === 'error') && (
          <chakra.p __css={styles.subscribeSuccess}>{SUBSCRIBE_UNAVAILABLE_MESSAGE}</chakra.p>
        )}
      </chakra.div>

      {enableNameCapture && (
        <SubscribeModal
          isOpen={modalOpen}
          onClose={() => setModalOpen(false)}
          onSubmit={handleModalSubmit}
          privacyPolicyHref={privacyPolicyHref}
        />
      )}
    </div>
  );
};

// ---------------------------------------------------------------------------
// Contact icon row — rendered below the link list in the Contact column
// ---------------------------------------------------------------------------
// Figma: Icon-list has pt-4px (alias/space/100) above it and 4px internal gap between icons.
// hrefs sourced from Contentful FooterConfigEntry (HPC-034). Until that integration lands,
// all hrefs are undefined and each icon renders as a non-interactive but labelled <span> —
// visible in the layout and announced by screen readers, but absent from the tab order.
// See the inline note on the fallback branch below for the full a11y reasoning.
// When a href arrives it switches to a live <a>, no other changes needed.
type ContactIconRowProps = {
  phoneHref?: string; // locale-aware tel: href from Contentful
  whatsAppHref?: string; // WhatsApp URL from Contentful
  emailHref?: string; // mailto: address from Contentful
};

type ContactLink = { href?: string; label: string; icon: 'phone' | 'whatsapp' | 'email' };

/**
 * True when following the href would navigate away from the storefront.
 *
 * Takes `string | undefined` rather than `string` so the caller does not need an `as string`
 * to satisfy it inside an isSafeHref branch. isSafeHref returns a plain boolean, which carries
 * no narrowing, and a `href is string` predicate would be unsound — an unsafe value like
 * `javascript:void(0)` is a string that returns false, so the else branch would narrow to
 * `undefined` incorrectly. An absent href never leaves the site, so `?? ''` is the honest answer.
 *
 * Derived from the scheme rather than keyed to a channel name: tel: and mailto: hand off to
 * the OS dialer or mail client and never navigate, so a target on them does nothing. An
 * http(s) channel — WhatsApp today — is a real cross-origin navigation and opens in a new
 * tab so a shopper mid-browse does not lose the site. Any future http(s) channel inherits
 * this without another edit here.
 */
const leavesTheSite = (href: string | undefined): boolean => /^https?:/i.test(href ?? '');

/** WCAG 3.2.5 — a link that opens a new tab has to say so in its accessible name. */
const NEW_TAB_SUFFIX = ' — opens in a new tab';

const ContactIconRow = ({ phoneHref, whatsAppHref, emailHref }: ContactIconRowProps) => {
  const styles = useMultiStyleConfig(ZIMM_FOOTER_RECIPE, {});
  const links: ContactLink[] = [
    { href: phoneHref, label: 'Call us', icon: 'phone' },
    { href: whatsAppHref, label: 'WhatsApp', icon: 'whatsapp' },
    { href: emailHref, label: 'Email us', icon: 'email' },
  ];
  return (
    <chakra.div __css={styles.contactRow}>
      {links.map(({ href, label, icon }) =>
        // isSafeHref, not a truthiness check: these arrive from Contentful, so a
        // javascript:/data:/protocol-relative value would otherwise be rendered
        // straight onto an anchor. Rejected values fall through to the span below,
        // which is already the correct treatment for "no usable destination".
        isSafeHref(href) ? (
          <chakra.a
            key={icon}
            href={href}
            // rel is explicit rather than relying on target="_blank" implying noopener:
            // that is browser default behaviour, not a guarantee, and noreferrer also
            // stops the storefront URL leaking to the third party.
            {...(leavesTheSite(href) ? { target: '_blank', rel: 'noopener noreferrer' } : {})}
            aria-label={leavesTheSite(href) ? `${label}${NEW_TAB_SUFFIX}` : label}
            __css={styles.contactIconLink}
          >
            <ZimmIcon type={icon} size="md" aria-hidden={true} />
          </chakra.a>
        ) : (
          // Fallback for a channel with no usable destination — either the field is absent
          // for this storefront, or isSafeHref rejected the value. Both reach here, and both
          // want the same treatment. NON-INTERACTIVE but PERCEIVABLE:
          //   - <span>: no href, no tabIndex, so nothing promises an action that cannot be
          //     performed (avoids the WCAG 2.4.4 / 3.2.4 false affordance).
          //   - labelled, not aria-hidden: ZimmIcon emits role="img" + aria-label, so screen
          //     reader users learn the channel exists instead of getting silence (avoids the
          //     1.1.1 information loss the previous aria-hidden caused).
          // Not dead code: contact channels are optional per storefront, so a locale that
          // supplies only e.g. email still renders the other two icons this way.
          <chakra.span key={icon} __css={styles.contactIconLink}>
            <ZimmIcon type={icon} size="md" aria-label={label} />
          </chakra.span>
        ),
      )}
    </chakra.div>
  );
};

// ---------------------------------------------------------------------------
// Bottom bar
// ---------------------------------------------------------------------------
type BottomBarProps = {
  copyrightYear: number;
  copyrightOwner: string;
  legalLinks: ReadonlyArray<{ label: string; href: string }>;
};

const BottomBar = ({ copyrightYear, copyrightOwner, legalLinks }: BottomBarProps) => {
  const styles = useMultiStyleConfig(ZIMM_FOOTER_RECIPE, {});
  return (
    <chakra.div __css={styles.bottomBar}>
      <chakra.div __css={styles.bottomInner}>
        <chakra.button
          type="button"
          aria-label="Change locale"
          __css={styles.localeButton}
          // PLACEHOLDER: wire to locale selector once available.
          // Label and destination are hardcoded until sourced from active locale/site config.
          onClick={undefined}
        >
          {/* localeText = Figma "footer-item": py-8px on text only, icon sits outside.
                        Typography and colour are inherited from the parent localeButton theme. */}
          <chakra.span __css={styles.localeText}>{LOCALE_LABEL_PLACEHOLDER}</chakra.span>
