import {chromium} from '/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/node_modules/playwright-core/index.mjs';

const BASE = 'http://localhost:3000';
const out = [];
const log = (...a) => { const s = a.join(' '); out.push(s); console.log(s); };

const browser = await chromium.launch();

async function probe(width, height, path, label) {
  const ctx = await browser.newContext({viewport: {width, height}, deviceScaleFactor: 1});
  const page = await ctx.newPage();
  page.on('pageerror', () => {});
  try {
    await page.goto(BASE + path, {waitUntil: 'domcontentloaded', timeout: 60000});
  } catch (e) { log(`!! goto failed ${path} @${width}: ${e.message.split('\n')[0]}`); await ctx.close(); return null; }
  // wait for footer
  try { await page.waitForSelector('footer[role="contentinfo"]', {timeout: 45000}); }
  catch (e) { log(`!! NO footer[role=contentinfo] on ${path} @${width}px  (${label})`); 
    const anyFooter = await page.locator('footer').count();
    log(`   <footer> count on page: ${anyFooter}`);
    if (anyFooter) log('   footer text: ' + (await page.locator('footer').first().innerText()).replace(/\n/g,' | ').slice(0,300));
    await ctx.close(); return null; }
  await page.waitForTimeout(1200);

  const data = await page.evaluate(() => {
    const f = document.querySelector('footer[role="contentinfo"]');
    const r = (el) => { if (!el) return null; const b = el.getBoundingClientRect(); return {x: +b.x.toFixed(1), y: +b.y.toFixed(1), w: +b.width.toFixed(1), h: +b.height.toFixed(1)}; };
    // nav column headings
    const headings = [...f.querySelectorAll('p')].filter(p => /^(About|Contact|Help)$/i.test(p.textContent.trim()));
    const cols = headings.map(h => ({label: h.textContent.trim(), box: r(h.parentElement), headingBox: r(h)}));
    // subscribe submit button
    const allBtns = [...f.querySelectorAll('button')].map(b => ({
      label: (b.getAttribute('aria-label') || b.textContent.trim() || '(none)').slice(0,40),
      box: r(b),
      type: b.getAttribute('type'),
    }));
    const emailInput = r(f.querySelector('input[type="email"], input[name="footer-email"]'));
    // contact icon links
    const contact = [...f.querySelectorAll('a[href^="tel:"], a[href^="mailto:"], a[href*="wa.me"]')].map(a => ({href: a.getAttribute('href'), aria: a.getAttribute('aria-label'), box: r(a)}));
    // legal links + nav links
    const navLinks = [...f.querySelectorAll('ul a')].map(a => ({t: a.textContent.trim().slice(0,30), box: r(a)}));
    const legal = [...f.querySelectorAll('a')].filter(a => /Accessibility|Terms|Privacy|Modern Slavery|Cookie/i.test(a.textContent)).map(a => ({t: a.textContent.trim(), box: r(a)}));
    // locale button text
    const localeBtn = [...f.querySelectorAll('button')].find(b => b.getAttribute('aria-label') === 'Change locale');
    return {
      footer: r(f),
      docWidth: document.documentElement.scrollWidth,
      cols, allBtns, emailInput, contact, navLinks, legal,
      localeText: localeBtn ? localeBtn.textContent.trim() : null,
      copyright: [...f.querySelectorAll('span')].map(s=>s.textContent.trim()).find(t=>/Copyright/i.test(t)) || null,
      footerHTMLlen: f.outerHTML.length,
      lang: document.documentElement.lang,
    };
  });

  log(`\n### ${label}  [${path} @ ${width}x${height}]`);
  log(`  html lang=${data.lang}  docScrollWidth=${data.docWidth}`);
  log(`  footer box: ${JSON.stringify(data.footer)}`);
  log(`  localeText: ${JSON.stringify(data.localeText)}`);
  log(`  copyright: ${JSON.stringify(data.copyright)}`);
  log(`  nav columns (${data.cols.length}):`);
  for (const c of data.cols) log(`    ${c.label.padEnd(9)} colBox=${JSON.stringify(c.box)}`);
  log(`  emailInput: ${JSON.stringify(data.emailInput)}`);
  log(`  buttons:`);
  for (const b of data.allBtns) log(`    "${b.label}" type=${b.type} box=${JSON.stringify(b.box)}`);
  log(`  contact anchors:`);
  for (const c of data.contact) log(`    ${c.href}  aria="${c.aria}" box=${JSON.stringify(c.box)}`);
  log(`  nav link count=${data.navLinks.length}; first 3: ${JSON.stringify(data.navLinks.slice(0,3))}`);
  log(`  legal links (${data.legal.length}): ${data.legal.map(l=>`${l.t}[${l.box.w}x${l.box.h}]`).join(', ')}`);
  await page.screenshot({path: `/tmp/zfooter/${label.replace(/[^a-z0-9]+/gi,'_')}.png`, fullPage: false, clip: {x:0, y: Math.max(0,data.footer.y), width: Math.min(width, data.docWidth), height: Math.min(data.footer.h, 2000)}}).catch(()=>{});
  await ctx.close();
  return data;
}

// AC4 mobile stacking
await probe(375, 812, '/', 'mobile-375-home');
await probe(402, 874, '/', 'mobile-402-home');
