await probe(1440, 900, '/fr-eu/', 'desktop-EU-fr');
await probe(1440, 900, '/en-ae/', 'desktop-ME');

await browser.close();
import fs from 'fs';
fs.writeFileSync('/tmp/zfooter/results.txt', out.join('\n'));
