import { breakpoints } from '../foundation/gridSystem';

// `tablet` mirrors the confirmed foundation token `breakpoints.md` — imported rather than
// retyped so the two cannot drift apart. `tabletWide` and `desktop` have no foundation
// equivalent yet; `desktop` additionally conflicts with Chakra's lg (62em) and xl (80em),
// which is why every desktop rule below is a raw @media rather than a responsive prop.
//
// theme/components/ otherwise avoids direct foundation/ imports in favour of --zimm-* CSS
// vars. Breakpoints are a deliberate exception: media queries cannot consume var().
// px ÷ 16; WCAG 1.4.4 requires em so queries shift with browser zoom.
const BP = {
  tablet: breakpoints.md, // Figma: alias/breakpoint/tablet — 768px
  tabletWide: '53.75em', // Figma: alias/breakpoint/tablet-wide — 860px (no foundation equivalent)
  desktop: '64em', // Figma: alias/breakpoint/desktop — 1024px (≠ Chakra lg=62em / xl=80em)
} as const;

// Provisional spacing/size values — kept here as named references until the UI designer
// confirms the token in foundation/spacing.ts or foundation/sizes.ts.
//
// SPACE_SECTION and SIZE_COL_NAV are NOT missing tokens: --zimm-scale-1200 (48px) and
// --zimm-scale-3500 (140px) already carry the same values. They are deliberately kept as
// rem here because those two foundation aliases are px, which does not scale under browser
// zoom (WCAG 1.4.4 — see overrideStyling.md Units). Collapse them onto the vars only once
// the foundation aliases move to rem.
const SPACE_SECTION = '3rem'; // alias/space/section (48px)
const SIZE_COL_NAV = '8.75rem'; // alias/size/footer/col-width-nav (140px)
const SIZE_COL_SUB = '20rem'; // alias/size/footer/col-width-subscribe (320px)
const SIZE_COL_MAP = '37.5rem'; // alias/size/footer/col-width-sitemap (600px)
const COLOUR_HALF_INV = 'rgba(255, 255, 255, 0.5)'; // alias/color/opacity-50-inverse
const SIZE_MODAL_SUB = '30rem'; // alias/size/modal/footer (480px)
const SIZE_SUB_BODY_MAX = '12.5rem'; // alias/size/footer/subscribe-body-max (200px)
// Reserved height for the subscribe control slot, so swapping the field for the result message
// cannot re-flow the footer. 2.8125rem = 45px, the height ZimmInputAction currently renders
// (36px content + 4px/4px padding + 1px border). PROVISIONAL: Figma's success state keeps a
// Textfield instance at 320x59 (node 4019:46044 > Stay In Touch Section), so the designed slot
// is 59px in both states — there is no token for it and actionSizes.height offers only 52/40.
// Pending Kiera. rem, not px: the slot holds text and must grow with root font-size (WCAG 1.4.4).
const SIZE_SUBSCRIBE_SLOT = '2.8125rem';

// ─── Parts that carry a conditional variant ────────────────────────────────
// Three call sites in footer/index.tsx used to compose styles inline: two identical
// `...(showContactChannels ? {paddingLeft:'2xs'} : {})` spreads (verbatim duplication) and a
// `sx={label.includes(NBSP) ? {width:'min-content'} : undefined}`. Both are style values living
// outside the theme, which overrideStyling.md puts here. Each base object is declared once
// below and spread into its variant, so a variant cannot drift from its base; the *selection*
// between them stays at the call site as a plain predicate, which is all that belongs there.

// The Contact column's heading and its link items sit 4px in — Figma wrapper 40000407:22289.
const CONTACT_INDENT = { paddingLeft: '2xs' };

// Nav column headings (About / Contact / Help) — Figma "Default/Navigation".
// fontFamily overrides the heading family textStyles.navigation carries:
// Figma binds brand/font/family/body here (node 40000407:11736).
const COLUMN_HEADING_BASE = {
  textStyle: 'navigation',
  fontFamily: 'var(--zimm-font-family-body)',
  margin: 0,
  color: 'var(--zimm-color-text-inverse-grey)', // alias/color/text/inverse/subtle
};

// display:flex, not the default list-item. ZimmNavItem renders an inline-flex <a> of
// exactly 24px, but a block-level <li> wraps it in a line box whose 24px strut adds
// descender space below the baseline — measured 25.5px against the anchor's 24px. That
// 1.5px leaked once per row (and 3px on the wrapped "Acknowledgement of Country"),
// making the links column 9px taller than Figma's 158px. Making the <li> a flex
// container removes the line box entirely, so its height is just the anchor's.
const LINK_LIST_ITEM_BASE = { listStyle: 'none', display: 'flex' };

