//   • Non-responsive colour tokens (container, bottomBar)
//   • All responsive layout styles for each named part — consumed via __css in footer/index.tsx
//   • localeButton typography (textStyle token) + interactive states (_focusVisible)
//
// FooterStyles <style> tag is removed; no className-based CSS or !important guards remain.
// Chakra controls injection order via Emotion, so specificity is predictable.
