  parts: [
    'container',
    'main',
    'contentRow',
    'subscribe',
    'subscribeHeading',
    'subscribeBody',
    'subscribeControl',
    'subscribeSuccess',
    'subscribeModalPanel',
    'modalOverlay',
    'modalTitle',
    'modalField',
    'modalFieldLast',
    'modalConsent',
    'modalConsentLink',
    'modalDisclaimer',
    'modalActions',
    'links',
    'linksInner',
    'linkCol',
    'logo',
    'columnHeading',
    'columnHeadingContact',
    'linkList',
    'linkListItem',
    'linkListItemContact',
    'linkListItemHug',
    'contactRow',
    'contactIconLink',
    'logoButton',
    'copyright',
    'legalLink',
    'bottomBar',
    'bottomInner',
    'bottomRight',
    'legalGrid',
    'localeText',
    'localeButton',
  ],
  baseStyle: {
    // ─── Root container ────────────────────────────────────────────────
    container: {
      backgroundColor: 'background.05',
      width: '100%',
