  [`@media (min-width: ${BP.tablet})`]: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    gap: 0,
    padding: `var(--zimm-scale-4xl) var(--zimm-scale-3xl) ${SPACE_SECTION}`,
  },
},

// Subscribe column — capped at 320px at every breakpoint
subscribe: {
  maxWidth: SIZE_COL_SUB,
  [`@media (min-width: ${BP.tablet})`]: {
    flex: `0 0 ${SIZE_COL_SUB}`,
    maxWidth: 'none',
  },
},

// Subscribe heading — Figma node 40000461:10415 binds brand/font/lineHeight/450 (18px).
// Unlike nav column headings (unbound 100%), this heading has a bound token.
