     2	import { Button as ChakraButton, IconButton } from '@chakra-ui/react';
     3	import { ZimmIcon } from '../zimmIcon';
     4	import type { ZimmIconType, ZimmIconSize } from '../zimmIcon';
     5	
     6	// All hover/press/focus/disabled interaction states live in theme/components/button.ts.
     7	// ZimmButton is a thin mapping layer: Zimmermann props (inverse, large/medium) → Chakra
     8	// variant/size names that button.ts recognises.
     9	
    10	type ZimmButtonBaseProps = {
    11	  /** Visible label (primary/secondary) or aria-label (icon variant — no visible text). */
    12	  label: string;
    13	  type?: 'button' | 'submit' | 'reset';
    14	  disabled?: boolean;
    15	  inverse?: boolean;
    16	  onClick?: () => void;
    17	  style?: CSSProperties;
    18	};
    19	
    20	type ZimmLabelButtonProps = ZimmButtonBaseProps & {
    21	  variant?: 'primary' | 'secondary';
    22	  size?: 'large' | 'medium';
    23	  fullWidth?: boolean;
    24	};
    25	
    26	type ZimmIconButtonProps = ZimmButtonBaseProps & {
    27	  variant: 'icon';
    28	  icon: ZimmIconType;
    29	  /** Icon render size — one of the iconSizes keys ('sm' | 'md' | 'lg'). Defaults to 'md' (16px). */
    30	  size?: ZimmIconSize;
    31	};
    32	
    33	type ZimmButtonProps = ZimmLabelButtonProps | ZimmIconButtonProps;
    34	
    35	const ICON_SIZE_DEFAULT: ZimmIconSize = 'md';
    36	
    37	/** Atom — labelled button (primary/secondary) or icon-only button. All visual states
    38	 *  are handled by `theme/components/button.ts` — no React state for hover/press/focus. */
    39	export const ZimmButton = (props: ZimmButtonProps) => {
    40	  const { label, type = 'button', disabled = false, inverse = false, onClick, style } = props;
    41	
    42	  if (props.variant === 'icon') {
    43	    return (
    44	      <IconButton
    45	        aria-label={label}
    46	        type={type}
    47	        isDisabled={disabled}
    48	        onClick={onClick}
    49	        variant={inverse ? 'iconInverse' : 'icon'}
    50	        size="icon"
    51	        icon={<ZimmIcon type={props.icon} size={props.size ?? ICON_SIZE_DEFAULT} aria-hidden={true} />}
    52	        style={style}
    53	      />
    54	    );
    55	  }
    56	
    57	  const variant = props.variant ?? 'primary';
    58	  const size = props.size === 'medium' ? 'sm' : 'lg';
    59	  // Maps inverse prop to the *Inverse variant suffix defined in button.ts.
    60	  const chakraVariant = `${variant}${inverse ? 'Inverse' : ''}`;
    61	
    62	  return (
    63	    <ChakraButton
    64	      type={type}
    65	      isDisabled={disabled}
    66	      onClick={onClick}
    67	      variant={chakraVariant}
    68	      size={size}
    69	      width={props.fullWidth ? '100%' : undefined}
    70	      style={style}
    71	    >
    72	      {label}
    73	    </ChakraButton>
    74	  );
    75	};
