cat > /tmp/zfooter/btn.mjs <<'EOF'
import {chromium} from '/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/node_modules/playwright-core/index.mjs';
const b = await chromium.launch();
const ctx = await b.newContext({viewport:{width:1440,height:900}});
const p = await ctx.newPage();
await p.goto('http://localhost:3000/', {waitUntil:'domcontentloaded'});
await p.waitForSelector('footer[role="contentinfo"]');
await p.waitForTimeout(1500);
const r = await p.evaluate(() => {
  const f = document.querySelector('footer[role="contentinfo"]');
  const btn = [...f.querySelectorAll('button')].find(x => (x.getAttribute('aria-label')||'') === 'Subscribe');
  const cs = getComputedStyle(btn);
  const bb = btn.getBoundingClientRect();
  const svg = btn.querySelector('svg');
  const parent = btn.parentElement;
  const pcs = getComputedStyle(parent);
  const input = f.querySelector('input[type="email"]');
  const ics = getComputedStyle(input);
  // the field wrapper (input + trailing)
  const wrap = input.closest('div');
  const wcs = wrap ? getComputedStyle(wrap) : null;
  return {
    btn: {box:{w:+bb.width.toFixed(2),h:+bb.height.toFixed(2)},
      padding: cs.padding, minWidth: cs.minWidth, minHeight: cs.minHeight, height: cs.height, width: cs.width,
      boxSizing: cs.boxSizing, display: cs.display, className: btn.className, cls: btn.getAttribute('class')},
    svg: svg ? {w:+svg.getBoundingClientRect().width.toFixed(2), h:+svg.getBoundingClientRect().height.toFixed(2), cs:{w:getComputedStyle(svg).width,h:getComputedStyle(svg).height}} : null,
    parent: {tag:parent.tagName, cls:parent.getAttribute('class'), display:pcs.display, padding:pcs.padding, w:+parent.getBoundingClientRect().width.toFixed(2), h:+parent.getBoundingClientRect().height.toFixed(2)},
    input: {h:+input.getBoundingClientRect().height.toFixed(2), padding: ics.padding, fontSize: ics.fontSize},
    wrap: wcs ? {h:+wrap.getBoundingClientRect().height.toFixed(2), padding:wcs.padding, display:wcs.display, alignItems:wcs.alignItems} : null,
    // ancestor chain of btn up to footer
    chain: (()=>{const out=[];let e=btn;while(e && e!==f){const c=getComputedStyle(e);const bx=e.getBoundingClientRect();out.push(`${e.tagName}.${(e.getAttribute('class')||'').split(' ')[0]} ${bx.width.toFixed(1)}x${bx.height.toFixed(1)} pad=${c.padding} disp=${c.display}`);e=e.parentElement;}return out;})(),
  };
});
console.log(JSON.stringify(r,null,2));
await b.close();
EOF
