import {chromium} from '/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/node_modules/playwright-core/index.mjs';
const b = await chromium.launch();
for (const w of [375, 383, 384, 390, 393, 402, 412, 430, 600, 767]) {
  const ctx = await b.newContext({viewport:{width:w,height:800}});
  const p = await ctx.newPage();
  await p.goto('http://localhost:3000/', {waitUntil:'domcontentloaded'});
  await p.waitForSelector('footer[role="contentinfo"]');
  await p.waitForTimeout(700);
  const r = await p.evaluate(() => {
    const f = document.querySelector('footer[role="contentinfo"]');
    const hs = [...f.querySelectorAll('p')].filter(x=>/^(About|Contact|Help)$/i.test(x.textContent.trim()));
    return hs.map(h=>{const b=h.parentElement.getBoundingClientRect();return `${h.textContent.trim()}@x${b.x.toFixed(0)},y${b.y.toFixed(0)}`;});
  });
  const rows = new Set(r.map(s=>s.split(',y')[1])).size;
  console.log(`${String(w).padStart(4)}px  rows=${rows}  ${rows===3?'STACKED (AC4 ok)':'WRAPPED 2-col (AC4 fail)'}  ${r.join('  ')}`);
  await ctx.close();
}
await b.close();
EOF
